import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.DFlFRONG.js";const g=JSON.parse('{"title":"TeamOne Proxy Server Installation Guide – SSL Managed by Load Balancer","description":"","frontmatter":{},"headers":[],"relativePath":"proxy-server/installation-load-balancer-ssl.md","filePath":"proxy-server/installation-load-balancer-ssl.md"}'),n={name:"proxy-server/installation-load-balancer-ssl.md"};function r(o,e,l,p,h,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="teamone-proxy-server-installation-guide-–-ssl-managed-by-load-balancer" tabindex="-1">TeamOne Proxy Server Installation Guide – SSL Managed by Load Balancer <a class="header-anchor" href="#teamone-proxy-server-installation-guide-–-ssl-managed-by-load-balancer" aria-label="Permalink to &quot;TeamOne Proxy Server Installation Guide – SSL Managed by Load Balancer&quot;">​</a></h1><p>This guide describes how to install the TeamOne Proxy Server when the SSL/TLS certificate is managed by a customer load balancer.</p><p>In this deployment model:</p><ul><li>users connect to the TeamOne endpoint over HTTPS</li><li>the load balancer manages the SSL/TLS certificate and HTTPS connection</li><li>the load balancer forwards HTTP traffic to the TeamOne Proxy Server</li><li>TeamOne Proxy Server uses TCP port <code>80</code> as the default HTTP listener port</li><li>SSL certificate and private key files are not installed on the TeamOne Proxy Server</li></ul><p>For questions or assistance, contact <strong><a href="mailto:teamone@succeedium.com" target="_blank" rel="noreferrer">teamone@succeedium.com</a></strong>.</p><h2 id="step-1-download-the-teamone-proxy-server-archive" tabindex="-1">Step 1: Download the TeamOne Proxy Server archive <a class="header-anchor" href="#step-1-download-the-teamone-proxy-server-archive" aria-label="Permalink to &quot;Step 1: Download the TeamOne Proxy Server archive&quot;">​</a></h2><p>Navigate to the directory where you want to install the TeamOne Proxy Server.</p><p>Download <code>teamone-server-distr.zip</code> using the download link provided by Succeedium.</p><p>If the target server does not have internet access, download the archive on a computer with internet access and copy it to the target server.</p><p>The downloaded file should be available as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>teamone-server-distr.zip</span></span></code></pre></div><h2 id="step-2-unzip-the-archive" tabindex="-1">Step 2: Unzip the archive <a class="header-anchor" href="#step-2-unzip-the-archive" aria-label="Permalink to &quot;Step 2: Unzip the archive&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr.zip</span></span></code></pre></div><p>This creates the <code>teamone-server-distr</code> directory containing the TeamOne Proxy Server application, Docker images, and configuration templates.</p><h2 id="step-3-create-the-configuration-files" tabindex="-1">Step 3: Create the configuration files <a class="header-anchor" href="#step-3-create-the-configuration-files" aria-label="Permalink to &quot;Step 3: Create the configuration files&quot;">​</a></h2><p>Create the TeamOne environment configuration file if it does not already exist:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> teamone-server-distr/config/.env ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/config/.env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/config/.env</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>For a deployment where SSL/TLS is managed by a load balancer, use the HTTP Nginx configuration template:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> teamone-server-distr/config/default.conf ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/config/nginx-http.conf.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/config/default.conf</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>The <code>nginx-http.conf.example</code> template configures the TeamOne Proxy Server to receive HTTP traffic from the load balancer, using TCP port <code>80</code> as the default listener port.</p><h2 id="step-4-configure-teamone" tabindex="-1">Step 4: Configure TeamOne <a class="header-anchor" href="#step-4-configure-teamone" aria-label="Permalink to &quot;Step 4: Configure TeamOne&quot;">​</a></h2><p>Review and update:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>teamone-server-distr/config/.env</span></span></code></pre></div><p>Configure the approved IBM Planning Analytics / TM1 hosts and, where applicable, the Cognos SSO gateway host.</p><p>See the full configuration reference:</p><p><a href="./configuration.html"><strong>TeamOne Proxy Server Configuration</strong></a></p><h2 id="step-5-load-the-docker-images" tabindex="-1">Step 5: Load the Docker images <a class="header-anchor" href="#step-5-load-the-docker-images" aria-label="Permalink to &quot;Step 5: Load the Docker images&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/images/teamone-server-distr.tar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/images/teamone-nginx-distr.tar</span></span></code></pre></div><h2 id="step-6-start-the-teamone-proxy-server" tabindex="-1">Step 6: Start the TeamOne Proxy Server <a class="header-anchor" href="#step-6-start-the-teamone-proxy-server" aria-label="Permalink to &quot;Step 6: Start the TeamOne Proxy Server&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><h2 id="step-7-configure-the-load-balancer" tabindex="-1">Step 7: Configure the load balancer <a class="header-anchor" href="#step-7-configure-the-load-balancer" aria-label="Permalink to &quot;Step 7: Configure the load balancer&quot;">​</a></h2><p>Configure the customer load balancer to provide the external HTTPS endpoint for TeamOne.</p><p>The recommended traffic flow is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Browser</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTPS / TLS 443</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Customer Load Balancer</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTP 80</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>TeamOne Proxy Server</span></span></code></pre></div><p>The load balancer should:</p><ul><li>listen for external HTTPS/TLS traffic on TCP port <code>443</code></li><li>use the customer-managed SSL/TLS certificate</li><li>forward traffic to the TeamOne Proxy Server over HTTP</li><li>use TCP port <code>80</code> as the default TeamOne Proxy Server target port</li><li>allow traffic only through the customer-approved network path</li></ul><p>The TeamOne Proxy Server should not be directly exposed to the public internet.</p><p>A publicly trusted certificate, an internal CA-issued certificate, or a self-signed certificate may be used at the load balancer level, provided the certificate is trusted by the users&#39; devices and browsers.</p><h2 id="step-8-verify-the-teamone-proxy-server" tabindex="-1">Step 8: Verify the TeamOne Proxy Server <a class="header-anchor" href="#step-8-verify-the-teamone-proxy-server" aria-label="Permalink to &quot;Step 8: Verify the TeamOne Proxy Server&quot;">​</a></h2><p>Open the configured TeamOne Proxy Server URL in a browser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;teamone-proxy-fqdn&gt;</span></span></code></pre></div><p>Confirm that it displays:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TeamOne is up!</span></span></code></pre></div><h2 id="step-9-verify-tm1-connectivity" tabindex="-1">Step 9: Verify TM1 connectivity <a class="header-anchor" href="#step-9-verify-tm1-connectivity" aria-label="Permalink to &quot;Step 9: Verify TM1 connectivity&quot;">​</a></h2><p>After the TeamOne Proxy Server is running, confirm that it can reach an approved IBM Planning Analytics / TM1 REST API endpoint.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;teamone-proxy-fqdn&gt;/?url=https://&lt;tm1-host&gt;:&lt;tm1-rest-api-port&gt;/api/v1/$metadata</span></span></code></pre></div><p>If the TM1 REST API uses HTTP instead of HTTPS, use the corresponding <code>http://</code> TM1 URL.</p><p>If the TeamOne Proxy Server is not starting, is not reachable, or cannot connect to IBM Planning Analytics / TM1, see:</p><p><a href="./troubleshooting.html"><strong>TeamOne Proxy Server Troubleshooting</strong></a></p>`,50)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
